INSERT INTO public.exercises (id,name,body_part,equipment,target,secondary_muscles,instructions,description,difficulty,category) VALUES
('bw-reverse-lunge','Reverse Lunge','upper legs','body weight','quads',ARRAY['glutes','hamstrings']::text[],ARRAY['Stand tall with the feet hip width.','Brace lightly before the first repetition.','Step one foot back and lower the back knee towards the floor, then drive through the front heel to stand.','Keep the front shin vertical and the chest tall.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Reverse Lunge is a strength exercise for the quads with support from the glutes and hamstrings. Stand tall with the feet hip width. Step one foot back and lower the back knee towards the floor, then drive through the front heel to stand. Keep the front shin vertical and the chest tall.','beginner','strength'),
('bw-tuck-jump','Tuck Jump','upper legs','body weight','quads',ARRAY['calves','abs']::text[],ARRAY['Stand with the feet hip width and the knees soft.','Brace lightly before the first repetition.','Jump vertically driving the knees towards the chest and land softly on the mid foot.','Land quietly; noise means the landing needs more control.','Reset fully between repetitions.','Complete the prescribed repetitions, then rest as written.']::text[],'Tuck Jump is a plyometrics exercise for the quads with support from the calves and abs. Stand with the feet hip width and the knees soft. Jump vertically driving the knees towards the chest and land softly on the mid foot. Land quietly; noise means the landing needs more control.','advanced','plyometrics'),
('bw-skater-jump','Skater Jump','upper legs','body weight','glutes',ARRAY['quads','calves']::text[],ARRAY['Stand on one leg with a soft knee.','Brace lightly before the first repetition.','Bound sideways onto the other leg, absorb the landing and bound back.','Land and stick each repetition before pushing off again.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Skater Jump is a plyometrics exercise for the glutes with support from the quads and calves. Stand on one leg with a soft knee. Bound sideways onto the other leg, absorb the landing and bound back. Land and stick each repetition before pushing off again.','intermediate','plyometrics'),
('bw-lateral-bound','Lateral Bound','upper legs','body weight','glutes',ARRAY['quads','calves']::text[],ARRAY['Stand on one leg in a quarter squat.','Brace lightly before the first repetition.','Push off explosively to the side, land on the opposite leg and hold the landing for a beat.','Control the landing before chasing distance.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Lateral Bound is a plyometrics exercise for the glutes with support from the quads and calves. Stand on one leg in a quarter squat. Push off explosively to the side, land on the opposite leg and hold the landing for a beat. Control the landing before chasing distance.','advanced','plyometrics'),
('bw-crab-walk','Crab Walk','upper arms','body weight','triceps',ARRAY['glutes','abs']::text[],ARRAY['Sit with the hands behind the hips and the knees bent, then lift the hips.','Brace lightly before the first repetition.','Walk forwards and backwards keeping the hips high.','Keep the chest open and the shoulders down.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed distance or time, then rest as written.']::text[],'Crab Walk is a strength exercise for the triceps with support from the glutes and abs. Sit with the hands behind the hips and the knees bent, then lift the hips. Walk forwards and backwards keeping the hips high. Keep the chest open and the shoulders down.','beginner','strength'),
('bw-donkey-kick','Donkey Kick','upper legs','body weight','glutes',ARRAY['hamstrings','abs']::text[],ARRAY['Kneel on all fours with the hips over the knees.','Brace lightly before the first repetition.','Drive one heel towards the ceiling keeping the knee bent, then lower with control.','Squeeze the glute at the top and do not arch the low back.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Donkey Kick is a strength exercise for the glutes with support from the hamstrings and abs. Kneel on all fours with the hips over the knees. Drive one heel towards the ceiling keeping the knee bent, then lower with control. Squeeze the glute at the top and do not arch the low back.','beginner','strength'),
('bw-standing-toe-touch','Toe Touches','waist','body weight','abs',ARRAY['hamstrings']::text[],ARRAY['Lie supine with the legs extended to the ceiling.','Brace lightly before the first repetition.','Curl the shoulders up and reach the hands towards the toes, then lower with control.','Reach from the ribs, keeping the legs still.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Toe Touches is a strength exercise for the abs with support from the hamstrings. Lie supine with the legs extended to the ceiling. Curl the shoulders up and reach the hands towards the toes, then lower with control. Reach from the ribs, keeping the legs still.','beginner','strength'),
('bw-wide-push-up','Wide-Grip Push-Up','chest','body weight','pectorals',ARRAY['triceps','delts']::text[],ARRAY['Set up in a plank with the hands wider than the shoulders.','Brace lightly before the first repetition.','Lower the chest towards the floor with the elbows at forty-five degrees and press back up.','Keep one straight line from head to heels.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Wide-Grip Push-Up is a strength exercise for the pectorals with support from the triceps and delts. Set up in a plank with the hands wider than the shoulders. Lower the chest towards the floor with the elbows at forty-five degrees and press back up. Keep one straight line from head to heels.','beginner','strength'),
('kb-deadlift','Kettlebell Deadlift','upper legs','kettlebell','glutes',ARRAY['hamstrings','upper back']::text[],ARRAY['Stand with a kettlebell between the feet, hip width apart.','Brace lightly before the first repetition.','Hinge the hips back, grip the handle and stand tall by driving the hips forward.','The hips move back, not down; the spine stays long.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Kettlebell Deadlift is a strength exercise for the glutes with support from the hamstrings and upper back. Stand with a kettlebell between the feet, hip width apart. Hinge the hips back, grip the handle and stand tall by driving the hips forward. The hips move back, not down; the spine stays long.','beginner','strength'),
('kb-curl','Kettlebell Curl','upper arms','kettlebell','biceps',ARRAY['forearms']::text[],ARRAY['Stand tall holding a kettlebell in each hand by the handle.','Brace lightly before the first repetition.','Curl the bells towards the shoulders keeping the elbows pinned, then lower slowly.','Control the bell as it settles on the forearm.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Kettlebell Curl is a strength exercise for the biceps with support from the forearms. Stand tall holding a kettlebell in each hand by the handle. Curl the bells towards the shoulders keeping the elbows pinned, then lower slowly. Control the bell as it settles on the forearm.','beginner','strength'),
('kb-halo','Kettlebell Halo','shoulders','kettlebell','delts',ARRAY['upper back','abs']::text[],ARRAY['Stand tall holding a kettlebell upside down by the horns at chest height.','Brace lightly before the first repetition.','Circle the bell around the head close to the skull, then reverse the direction.','Keep the ribs down and the movement purely in the shoulders.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Kettlebell Halo is a mobility exercise for the delts with support from the upper back and abs. Stand tall holding a kettlebell upside down by the horns at chest height. Circle the bell around the head close to the skull, then reverse the direction. Keep the ribs down and the movement purely in the shoulders.','beginner','mobility'),
('bb-hip-thrust','Barbell Hip Thrust','upper legs','barbell','glutes',ARRAY['hamstrings','abs']::text[],ARRAY['Sit with the upper back against a bench and a padded barbell across the hips.','Brace lightly before the first repetition.','Drive through the heels to lift the hips to full extension, pause, and lower with control.','Finish with the ribs down and the glutes locked, never with a low-back arch.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Barbell Hip Thrust is a strength exercise for the glutes with support from the hamstrings and abs. Sit with the upper back against a bench and a padded barbell across the hips. Drive through the heels to lift the hips to full extension, pause, and lower with control. Finish with the ribs down and the glutes locked, never with a low-back arch.','intermediate','strength'),
('db-farmers-carry','Farmer''s Carry','waist','dumbbell','forearms',ARRAY['upper back','glutes']::text[],ARRAY['Stand tall holding a heavy dumbbell in each hand.','Brace lightly before the first step.','Walk with short controlled steps for the prescribed distance or time, staying tall.','Shoulders back and down, ribs stacked over the pelvis.','Keep the tempo controlled and the steps even.','Complete the prescribed distance or time, then rest as written.']::text[],'Farmer''s Carry is a strength exercise for the forearms with support from the upper back and glutes. Stand tall holding a heavy dumbbell in each hand. Walk with short controlled steps for the prescribed distance or time, staying tall. Shoulders back and down, ribs stacked over the pelvis.','beginner','strength'),
('db-renegade-row','Renegade Row','back','dumbbell','upper back',ARRAY['abs','biceps']::text[],ARRAY['Start in a plank gripping a dumbbell in each hand, feet wide.','Brace lightly before the first repetition.','Row one dumbbell to the ribs without rotating the hips, then change sides.','If the hips twist, widen the feet or lighten the load.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Renegade Row is a strength exercise for the upper back with support from the abs and biceps. Start in a plank gripping a dumbbell in each hand, feet wide. Row one dumbbell to the ribs without rotating the hips, then change sides. If the hips twist, widen the feet or lighten the load.','advanced','strength'),
('machine-pec-deck-fly','Pec Deck Fly','chest','leverage machine','pectorals',ARRAY['delts']::text[],ARRAY['Sit in the pec deck with the back flat and the elbows at chest height.','Brace lightly before the first repetition.','Bring the pads together in front of the chest, squeeze, and open slowly.','Keep the shoulders down and never force the stretch behind you.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Pec Deck Fly is a strength exercise for the pectorals with support from the delts. Sit in the pec deck with the back flat and the elbows at chest height. Bring the pads together in front of the chest, squeeze, and open slowly. Keep the shoulders down and never force the stretch behind you.','beginner','strength'),
('machine-rear-delt-fly','Rear Delt Machine Fly','shoulders','leverage machine','delts',ARRAY['upper back']::text[],ARRAY['Sit facing the pec deck pad with the arms forward at shoulder height.','Brace lightly before the first repetition.','Open the arms wide leading with the elbows, squeeze the shoulder blades, and return slowly.','Keep the chest on the pad and the neck relaxed.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Rear Delt Machine Fly is a strength exercise for the delts with support from the upper back. Sit facing the pec deck pad with the arms forward at shoulder height. Open the arms wide leading with the elbows, squeeze the shoulder blades, and return slowly. Keep the chest on the pad and the neck relaxed.','beginner','strength'),
('machine-ab-crunch','Machine Ab Crunch','waist','leverage machine','abs',ARRAY['obliques']::text[],ARRAY['Sit in the crunch machine with the pads on the chest and feet secured.','Brace lightly before the first repetition.','Curl the ribs towards the pelvis, pause, and return with control.','Move the spine, not the hips.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Machine Ab Crunch is a strength exercise for the abs with support from the obliques. Sit in the crunch machine with the pads on the chest and feet secured. Curl the ribs towards the pelvis, pause, and return with control. Move the spine, not the hips.','beginner','strength'),
('machine-back-extension-roman-chair','Back Extension (Roman Chair)','back','leverage machine','spine',ARRAY['glutes','hamstrings']::text[],ARRAY['Set the pad just below the hip bones on a Roman chair.','Brace lightly before the first repetition.','Hinge down under control and rise until the body is in one straight line.','Stop at straight; hyperextending gains nothing.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Back Extension (Roman Chair) is a strength exercise for the spine with support from the glutes and hamstrings. Set the pad just below the hip bones on a Roman chair. Hinge down under control and rise until the body is in one straight line. Stop at straight; hyperextending gains nothing.','beginner','strength'),
('machine-hip-thrust-press','Hip Thrust Machine Press','upper legs','leverage machine','glutes',ARRAY['hamstrings']::text[],ARRAY['Sit in the hip thrust machine with the pad over the hips.','Brace lightly before the first repetition.','Drive the hips into the pad to full extension, pause, and lower with control.','Squeeze the glutes at the top and keep the ribs down.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Hip Thrust Machine Press is a strength exercise for the glutes with support from the hamstrings. Sit in the hip thrust machine with the pad over the hips. Drive the hips into the pad to full extension, pause, and lower with control. Squeeze the glutes at the top and keep the ribs down.','beginner','strength'),
('machine-dip','Machine Dip','upper arms','leverage machine','triceps',ARRAY['pectorals','delts']::text[],ARRAY['Sit in the dip machine with the hands on the handles and the chest tall.','Brace lightly before the first repetition.','Press the handles down to full elbow extension, then return slowly.','Keep the shoulders down and the elbows tracking back.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Machine Dip is a strength exercise for the triceps with support from the chest and delts. Sit in the dip machine with the hands on the handles and the chest tall. Press the handles down to full elbow extension, then return slowly. Keep the shoulders down and the elbows tracking back.','beginner','strength'),
('cable-crossover-high-low','Cable Crossover (High to Low)','chest','cable','pectorals',ARRAY['delts','abs']::text[],ARRAY['Stand between two high pulleys with a handle in each hand and one foot forward.','Brace lightly before the first repetition.','Sweep the hands down and together in front of the hips, squeeze, and return slowly.','Keep a soft constant elbow angle throughout.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Cable Crossover (High to Low) is a strength exercise for the pectorals with support from the delts and abs. Stand between two high pulleys with a handle in each hand and one foot forward. Sweep the hands down and together in front of the hips, squeeze, and return slowly. Keep a soft constant elbow angle throughout.','intermediate','strength'),
('cable-crossover-low-high','Cable Crossover (Low to High)','chest','cable','pectorals',ARRAY['delts']::text[],ARRAY['Stand between two low pulleys with a handle in each hand.','Brace lightly before the first repetition.','Sweep the hands up and together in front of the chest, squeeze, and lower slowly.','Lead with the hands, not the shoulders.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions, then rest as written.']::text[],'Cable Crossover (Low to High) is a strength exercise for the pectorals with support from the delts. Stand between two low pulleys with a handle in each hand. Sweep the hands up and together in front of the chest, squeeze, and lower slowly. Lead with the hands, not the shoulders.','intermediate','strength')
